local SundialGnomonMaker = {}
local PRODUCTS = {
    iron_sundialgnomon = { name = "Železni solarski kazalec", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni solarski kazalec za solarne ure." },
    bronze_sundialgnomon = { name = "Bronast solarski kazalec", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast solarski kazalec za solarne ure." },
    silver_sundialgnomon = { name = "Srebrn solarski kazalec", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn solarski kazalec za solarne ure." },
    gilded_sundialgnomon = { name = "Pozlačen solarski kazalec", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen solarski kazalec za solarne ure." },
    jewel_set_sundialgnomon = { name = "Draguljast solarski kazalec", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast solarski kazalec za solarne ure." },
    royal_sovereign_sundialgnomon = { name = "Kraljevski suveren solarski kazalec", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren solarski kazalec z biseri za krono." },
}
local BUILDINGS = {
    sundialgnomon_workshop = { name = "Sundialgnomon delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sundialgnomon_house = { name = "Sundialgnomon hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sundialgnomon_atelier = { name = "Mojstrski sundialgnomon atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sundialgnomon_palace = { name = "Suverena sundialgnomon palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SundialGnomonMaker.ironStock = 16; SundialGnomonMaker.bronzeStock = 14; SundialGnomonMaker.woodStock = 10; SundialGnomonMaker.leatherStock = 8; SundialGnomonMaker.silverStock = 8; SundialGnomonMaker.goldStock = 6; SundialGnomonMaker.jewelStock = 4; SundialGnomonMaker.pearlStock = 4
SundialGnomonMaker.productStock = {}; SundialGnomonMaker.buildings = {}; SundialGnomonMaker.maker = nil; SundialGnomonMaker.activeMaking = {}; SundialGnomonMaker.totalProducts = 0; SundialGnomonMaker.dayTimer = 0
function SundialGnomonMaker.init() SundialGnomonMaker.ironStock=16; SundialGnomonMaker.bronzeStock=14; SundialGnomonMaker.woodStock=10; SundialGnomonMaker.leatherStock=8; SundialGnomonMaker.silverStock=8; SundialGnomonMaker.goldStock=6; SundialGnomonMaker.jewelStock=4; SundialGnomonMaker.pearlStock=4; SundialGnomonMaker.productStock={}; SundialGnomonMaker.buildings={}; SundialGnomonMaker.maker=nil; SundialGnomonMaker.activeMaking={}; SundialGnomonMaker.totalProducts=0; SundialGnomonMaker.dayTimer=0; print("[SundialGnomonMaker] Royal Sundial Gnomon Maker System initialized (6 products, 4 buildings)") end
function SundialGnomonMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SundialGnomonMaker.maker={name=n or ("Kazalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kazalec najet: %s (spretnost: %d)",SundialGnomonMaker.maker.name,s),"success") end; return true end
function SundialGnomonMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SundialGnomonMaker.build(id) local ok,e=SundialGnomonMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SundialGnomonMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SundialGnomonMaker.getQualityBonus() local b=0; for _,bd in ipairs(SundialGnomonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SundialGnomonMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SundialGnomonMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SundialGnomonMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SundialGnomonMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SundialGnomonMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SundialGnomonMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SundialGnomonMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SundialGnomonMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SundialGnomonMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SundialGnomonMaker.buildings==0 then return false,"Potrebna kazalna delavnica" end; if not SundialGnomonMaker.maker then return false,"Potreben kazalec" end; return true end
function SundialGnomonMaker.make(pt,qty) qty=qty or 1; local ok,e=SundialGnomonMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SundialGnomonMaker.ironStock=SundialGnomonMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SundialGnomonMaker.bronzeStock=SundialGnomonMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SundialGnomonMaker.woodStock=SundialGnomonMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SundialGnomonMaker.leatherStock=SundialGnomonMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SundialGnomonMaker.silverStock=SundialGnomonMaker.silverStock-d.silverCost*qty end; if d.goldCost then SundialGnomonMaker.goldStock=SundialGnomonMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SundialGnomonMaker.jewelStock=SundialGnomonMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SundialGnomonMaker.pearlStock=SundialGnomonMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SundialGnomonMaker.maker then t=math.max(1,t-math.floor(SundialGnomonMaker.maker.skill/13)) end; table.insert(SundialGnomonMaker.activeMaking,{id="sundialgnomon_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SundialGnomonMaker.completeMaking(m) local q=1.0+(SundialGnomonMaker.getQualityBonus()/100); if SundialGnomonMaker.maker then q=q+(SundialGnomonMaker.maker.skill/140) end; q=math.min(2.5,q); SundialGnomonMaker.productStock[m.productType]=(SundialGnomonMaker.productStock[m.productType] or 0)+m.quantity; SundialGnomonMaker.totalProducts=SundialGnomonMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SundialGnomonMaker.maker then SundialGnomonMaker.maker.itemsMade=SundialGnomonMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SundialGnomonMaker.maker.skill=math.min(100,SundialGnomonMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kazalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sundialgnomon.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SundialGnomonMaker.update(dt) if not _G.state then return end; SundialGnomonMaker.dayTimer=SundialGnomonMaker.dayTimer+dt; if SundialGnomonMaker.dayTimer>=30 then SundialGnomonMaker.dayTimer=0; for i=#SundialGnomonMaker.activeMaking,1,-1 do local m=SundialGnomonMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SundialGnomonMaker.completeMaking(m); table.remove(SundialGnomonMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SundialGnomonMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SundialGnomonMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SundialGnomonMaker.getStats() return {ironStock=SundialGnomonMaker.ironStock,bronzeStock=SundialGnomonMaker.bronzeStock,woodStock=SundialGnomonMaker.woodStock,leatherStock=SundialGnomonMaker.leatherStock,silverStock=SundialGnomonMaker.silverStock,goldStock=SundialGnomonMaker.goldStock,jewelStock=SundialGnomonMaker.jewelStock,pearlStock=SundialGnomonMaker.pearlStock,productStock=SundialGnomonMaker.productStock,numBuildings=#SundialGnomonMaker.buildings,hasMaker=SundialGnomonMaker.maker~=nil,makerName=SundialGnomonMaker.maker and SundialGnomonMaker.maker.name or "—",makerSkill=SundialGnomonMaker.maker and SundialGnomonMaker.maker.skill or 0,activeMaking=#SundialGnomonMaker.activeMaking,totalProducts=SundialGnomonMaker.totalProducts} end
return SundialGnomonMaker
